	/**
	* Merge request-only messages declared by an `agent/pre-step` handler.
	*
	* The contract is narrow on purpose: entries are plain strings, become user
	* messages with a plugin source, and are merged into this request snapshot
	* only. Nothing is appended to the session, so a later request cannot replay
	* them.
	*/
	withRequestMessages(request, messages) {
		if (!Array.isArray(messages) || messages.length === 0) return request;
		const transient = messages.filter((message) => typeof message === "string" && message.trim().length > 0).map((text) => createUserMessage({
			content: [{
				type: "text",
				text
			}],
			source: {
				kind: "plugin",
				form: "snapshot"
			}
		}));
		if (transient.length === 0) return request;
		return markAgentLoopRequest(Object.freeze({
			...request,
			messages: Object.freeze([...request.messages, ...transient])
		}));
	}
